        new("Menu.FpsOverlayHorizontal", new IniKey("Menu", "FpsOverlayHorizontal"), "FpsOverlayHorizontal", string.Empty, "Menu", 171, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables Horizontal FPS overlay layout\ntrue or false - Default (auto) is false"),
