        new("Menu.OverlaysUseTheme", new IniKey("Menu", "OverlaysUseTheme"), "OverlaysUseTheme", string.Empty, "Menu", 174, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Overlays uses the theme colors\ntrue or false - Default (auto) is false"),
        new("Menu.LightTheme", new IniKey("Menu", "LightTheme"), "LightTheme", string.Empty, "Menu", 175, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables Light Theme for Menu  \ntrue or false - Default (auto) is false"),
        new("Menu.AccentColorR", new IniKey("Menu", "AccentColorR"), "AccentColorR", string.Empty, "Menu", 176, SettingValueKind.Double, true, [], "auto", null, null, SourceComment: "Accent color for the menu\nR/G/B float colors values of the accent color for the menu\n0.0 to 1.0 - Default (auto) R: 0.0, G: 0.4, B: 0.77 (Blue)"),
        new("Menu.AccentColorG", new IniKey("Menu", "AccentColorG"), "AccentColorG", string.Empty, "Menu", 177, SettingValueKind.Double, true, [], "auto", null, null, SourceComment: ""),
