        new("Menu.BGColorA", new IniKey("Menu", "BGColorA"), "BGColorA", string.Empty, "Menu", 182, SettingValueKind.Double, true, [], "auto", null, null, SourceComment: "Background alpha for the menu\n0 is transparent and 1 is opaque\n0.0 to 1.0 - Default (auto) 0.99"),
        new("Spoofing.SpoofedVendorId", new IniKey("Spoofing", "SpoofedVendorId"), "SpoofedVendorId", string.Empty, "Spoofing", 183, SettingValueKind.Integer, true, [], "auto", null, null, SourceComment: "VendorID to spoof \n0x10de = Nvidia | 0x8086 = Intel | 0x1002 = AMD\nInteger value - Default (auto) is 0x10de"),
        new("Spoofing.SpoofedDeviceId", new IniKey("Spoofing", "SpoofedDeviceId"), "SpoofedDeviceId", string.Empty, "Spoofing", 184, SettingValueKind.Integer, true, [], "auto", null, null, SourceComment: "DeviceID to spoof \n0x2684 = 4090 | 0xE20B = B580 | 0x7550 9070 XT\nInteger value - Default (auto) is 0x2684 (4090)"),
        new("Spoofing.TargetVendorId", new IniKey("Spoofing", "TargetVendorId"), "TargetVendorId", string.Empty, "Spoofing", 185, SettingValueKind.Integer, true, [], "auto", null, null, SourceComment: "Target VendorID to be spoofed\nInteger value - Default (auto) is all"),
        new("Spoofing.TargetDeviceId", new IniKey("Spoofing", "TargetDeviceId"), "TargetDeviceId", string.Empty, "Spoofing", 186, SettingValueKind.Integer, true, [], "auto", null, null, SourceComment: "Target DeviceID to be spoofed\nDefault (auto) is all"),
        new("Spoofing.SpoofedGPUName", new IniKey("Spoofing", "SpoofedGPUName"), "SpoofedGPUName", string.Empty, "Spoofing", 187, SettingValueKind.String, true, [], "auto", null, null, SourceComment: "Spoofed GPU name\nNVIDIA GeForce RTX 4090 | Intel(R) Arc(TM) B580 Graphics | AMD Radeon RX 9070 XT\nDefault (auto) is NVIDIA GeForce RTX 4090"),
        new("Spoofing.StreamlineSpoofing", new IniKey("Spoofing", "StreamlineSpoofing"), "StreamlineSpoofing", string.Empty, "Spoofing", 188, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables GPU spoofing for Streamline, even if Dxgi spoofing is disabled for the rest of the game\nUsually allows for using Fakenvapi without spoofing the whole game, and sometimes DLSS/DLSSG\ntrue or false - Default (auto) is true"),
        new("Spoofing.Dxgi", new IniKey("Spoofing", "Dxgi"), "Dxgi", string.Empty, "Spoofing", 189, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables Nvidia GPU spoofing for DXGI (can be changed above to spoof other vendors)\ntrue or false - Default (auto) is true for AMD/Intel, false for Nvidia"),
        new("Spoofing.DxgiFactoryWrapping", new IniKey("Spoofing", "DxgiFactoryWrapping"), "DxgiFactoryWrapping", string.Empty, "Spoofing", 190, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables wrapping of DxgiFactory instead of hooking\nMight cause issues or help Nvidia cards with other mods\ntrue or false - Default (auto) is false"),
        new("Spoofing.DxgiBlacklist", new IniKey("Spoofing", "DxgiBlacklist"), "DxgiBlacklist", string.Empty, "Spoofing", 191, SettingValueKind.String, true, [], "auto", null, null, SourceComment: "Skips DXGI GPU spoofing when caller method in the list (example: slInit|slGetPluginFunction|nvapi_QueryInterface)\nBe careful this will disable spoofing for rest of the calls, also does not work on Linux\nmethod names seperated with pipe \"|\" - Default (auto) is disabled"),
        new("Spoofing.DxgiVRAM", new IniKey("Spoofing", "DxgiVRAM"), "DxgiVRAM", string.Empty, "Spoofing", 192, SettingValueKind.Integer, true, [], "auto", null, null, SourceComment: "Spoof amount of VRAM for DXGI\nSpoofed amount in GBs - Default (auto) is disabled"),
        new("Spoofing.Vulkan", new IniKey("Spoofing", "Vulkan"), "Vulkan", string.Empty, "Spoofing", 193, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables Nvidia GPU spoofing for Vulkan (can be changed above to spoof other vendors)\ntrue or false - Default (auto) is false"),
        new("Spoofing.VulkanExtensionSpoofing", new IniKey("Spoofing", "VulkanExtensionSpoofing"), "VulkanExtensionSpoofing", string.Empty, "Spoofing", 194, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables Nvidia extension spoofing for Vulkan\ntrue or false - Default (auto) is false"),
        new("Spoofing.VulkanVRAM", new IniKey("Spoofing", "VulkanVRAM"), "VulkanVRAM", string.Empty, "Spoofing", 195, SettingValueKind.Integer, true, [], "auto", null, null, SourceComment: "Spoof amount of VRAM for Vulkan\nSpoofed amount in GBs - Default (auto) is disabled"),
        new("Spoofing.SpoofHAGS", new IniKey("Spoofing", "SpoofHAGS"), "SpoofHAGS", string.Empty, "Spoofing", 196, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables spoofing of Hardware Accelerated GPU Scheduling\nRequired for Nukem's mod, also lets RTX40xx series users use DLSSG without HAGS enabled \ntrue or false - Default (auto) is false, unless DLSSG mod is enabled"),
        new("Spoofing.D3DFeatureLevel", new IniKey("Spoofing", "D3DFeatureLevel"), "D3DFeatureLevel", string.Empty, "Spoofing", 197, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables overriding of requested D3D feature level\ntrue or false - Default (auto) is false"),
        new("Spoofing.UEIntelAtomics", new IniKey("Spoofing", "UEIntelAtomics"), "UEIntelAtomics", string.Empty, "Spoofing", 198, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Prevents DirectX12 not supported error on UE games\nwith Intel cards when spoofing enabled\ntrue or false - Default (auto) is false"),
        new("Spoofing.Registry", new IniKey("Spoofing", "Registry"), "Registry", string.Empty, "Spoofing", 199, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Spoofs Vendor ID, Device ID and Driver Version at registry level\ntrue or false - Default (auto) is false"),
        new("Spoofing.RegistryDriver", new IniKey("Spoofing", "RegistryDriver"), "RegistryDriver", string.Empty, "Spoofing", 200, SettingValueKind.String, true, [], "auto", null, null, SourceComment: "Driver version to be spoofed at registry\nstring value - Default (auto) is 32.0.15.9155 (For Nvidia)"),
        new("Spoofing.User32", new IniKey("Spoofing", "User32"), "User32", string.Empty, "Spoofing", 201, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Spoofs Vendor ID, Device ID at User32 level\ntrue or false - Default (auto) is false"),
        new("Plugins.Path", new IniKey("Plugins", "Path"), "Path", string.Empty, "Plugins", 202, SettingValueKind.String, true, [], "auto", null, null, SourceComment: "Path that will be searched for same filename plugins (dxgi.dll, winmm.dll, etc.)\nDefault is plugins under OptiDllPath \".\\OptiScaler\\plugins\\\""),
        new("Plugins.LoadAsiPlugins", new IniKey("Plugins", "LoadAsiPlugins"), "LoadAsiPlugins", string.Empty, "Plugins", 203, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Lets OptiScaler load *.asi files in plugins folder\ntrue or false - Default (auto) is false"),
        new("Plugins.LateAsiPluginsDelay", new IniKey("Plugins", "LateAsiPluginsDelay"), "LateAsiPluginsDelay", string.Empty, "Plugins", 204, SettingValueKind.Integer, true, [], "auto", null, null, SourceComment: "Delay before injecting late-loaded *.asi files in plugins folder\nTo load an ASI plugin late, add -loadlate to its filename before the extension, e.g. \"myplugin-loadlate.asi\"\nInteger value in seconds - Default (auto) is 30"),
        new("Plugins.LoadSpecialK", new IniKey("Plugins", "LoadSpecialK"), "LoadSpecialK", string.Empty, "Plugins", 205, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Loads SpecialK64.dll from game's exe folder\nPlease create an empty SpecialK.dxgi file next to SpecialK64.dll\nto set SpecialK's working mode, otherwise it will not be activated\nBECAUSE OF STABILITY ISSUES, WILL NOT BE LOADED WHEN OPTIFG, DLSSG via SL or FSR-FG INPUTS ARE ENABLED\ntrue or false - Default (auto) is false"),
        new("Plugins.LoadReshade", new IniKey("Plugins", "LoadReshade"), "LoadReshade", string.Empty, "Plugins", 206, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Loads Reshade64.dll from game's exe folder\nRename Reshade dll to ReShade64.dll, put next to OptiScaler and set to true\ntrue or false - Default (auto) is false"),
        new("Plugins.LoadCustomAmdxc64OnRdna2", new IniKey("Plugins", "LoadCustomAmdxc64OnRdna2"), "LoadCustomAmdxc64OnRdna2", string.Empty, "Plugins", 207, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Loads custom amdxc64.dll for all detected RDNA 2 GPUs\nOptiScaler loads it from OptiDllPath, e.g. \".\\OptiScaler\\amdxc64.dll\"\ntrue or false - Default (auto) is false"),
        new("fakenvapi.UseFakenvapi", new IniKey("fakenvapi", "UseFakenvapi"), "UseFakenvapi", string.Empty, "fakenvapi", 208, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Use fakenvapi when nvapi64.dll is missing.\nfakenvapi replaces nvapi calls allowing for features like AntiLag 2 or XeLL to replace Reflex\nSometimes also required for DLSS/DLSSG to show up\ntrue or false - Default (auto) is true"),
        new("fakenvapi.ForceXeLL", new IniKey("fakenvapi", "ForceXeLL"), "ForceXeLL", string.Empty, "fakenvapi", 209, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Allow XeLL to work without FG on non-Intel cards, Requires updated libxell + libxess_fg\nDisables FG options\ntrue or false - Default (auto) is false"),
        new("fakenvapi.ForceLatencyFlex", new IniKey("fakenvapi", "ForceLatencyFlex"), "ForceLatencyFlex", string.Empty, "fakenvapi", 210, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Tries to use LatencyFlex even when better options are avaliable\nDoesn't take effect when using XeFG\ntrue or false - Default (auto) is false"),
        new("fakenvapi.LatencyFlexMode", new IniKey("fakenvapi", "LatencyFlexMode"), "LatencyFlexMode", string.Empty, "fakenvapi", 211, SettingValueKind.Enum, true, [new("0", "Conservative"), new("1", "Aggressive"), new("2", "ReflexIDs")], "auto", 0d, 2d, SourceComment: "Controls how latencyflex works\n0 = conservative\n1 = aggressive, will improve latency but in some cases will lower fps more than expected\n2 = use reflex frame ids, some games are not compatible (i.e. cyberpunk) and will fallback to aggressive\nDefault (auto) is 0"),
        new("fakenvapi.ForceReflex", new IniKey("fakenvapi", "ForceReflex"), "ForceReflex", string.Empty, "fakenvapi", 212, SettingValueKind.Enum, true, [new("0", "InGame"), new("1", "ForceDisable"), new("2", "ForceEnable")], "auto", 0d, 2d, SourceComment: "Force Reflex state, useful for games that only enable Reflex when using DLSSG without a separate toggle for Reflex\n0 - follow in-game setting, 1 - force disable, 2 - force enable\nDefault (auto) is 0"),
        new("NvApi.DisableFlipMetering", new IniKey("NvApi", "DisableFlipMetering"), "DisableFlipMetering", string.Empty, "NvApi", 213, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Disable FlipMetering\nFix the thick frametime graph caused by Nvidia's Flip Metering when using NukemFG, needs Fakenvapi to work\ntrue or false - Default (auto) is false for Nvidia, true for others"),
        new("Dx11withDx12.UseDelayedInit", new IniKey("Dx11withDx12", "UseDelayedInit"), "UseDelayedInit", string.Empty, "Dx11withDx12", 214, SettingValueKind.Integer, true, [], "auto", null, null, SourceComment: "Delay some operations during creation of D11wDx12 features to increase compatibility\ntrue or false - Default (auto) is false"),
        new("Dx11withDx12.DontUseNTShared", new IniKey("Dx11withDx12", "DontUseNTShared"), "DontUseNTShared", string.Empty, "Dx11withDx12", 215, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Prefer using D3D11_RESOURCE_MISC_SHARED, which is lower level\nand a bit more performant and possibly less compatible\ntrue or false - Default (auto) is true"),
        new("Hooks.EarlyHooking", new IniKey("Hooks", "EarlyHooking"), "EarlyHooking", string.Empty, "Hooks", 216, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Early hooking of kernel methods \nMay cause compatibility issues!!!\ntrue or false - Default (auto) is false"),
        new("Hooks.HookOriginalNvngxOnly", new IniKey("Hooks", "HookOriginalNvngxOnly"), "HookOriginalNvngxOnly", string.Empty, "Hooks", 217, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Skip hooking of local nvngx files and only hook nvngx at registry\nNeeded for Uniscaler + FG\ntrue or false - Default (auto) is false"),
        new("Hooks.UseNtdllHooks", new IniKey("Hooks", "UseNtdllHooks"), "UseNtdllHooks", string.Empty, "Hooks", 218, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Only hook ntdll.dll methods, skip kernel32.dll and kernelbase.dll hooks\ntrue or false - Default (auto) is true"),
        new("Sharpness.Shader", new IniKey("Sharpness", "Shader"), "Shader", string.Empty, "Sharpness", 219, SettingValueKind.Enum, true, [new("rcas", "RCAS"), new("da", "DepthAware"), new("lcda", "LocalContrastDepthAware")], "auto", null, null, SourceComment: "Options are:\nRCAS - AMD's Robust Contrast-Adaptive Sharpening\nDA - Enables Depth-based edge detection for sharpening.\n     Reduces sharpening across object boundaries to prevent halos and artifacts.\n     The farther away is the object, the more sharpening is applied (limited to 1.0)\n     Recommended for scenes with complex geometry or upscaling.\nLCDA - Local contrast version of the above DA\nrcas, da or lcda - Default (auto) is rcas"),
        new("Sharpness.OverrideSharpness", new IniKey("Sharpness", "OverrideSharpness"), "OverrideSharpness", string.Empty, "Sharpness", 220, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Override DLSS Sharpness parameter with fixed Sharpness value\ntrue or false - Default (auto) is false"),
        new("Sharpness.Sharpness", new IniKey("Sharpness", "Sharpness"), "Sharpness", string.Empty, "Sharpness", 221, SettingValueKind.Double, true, [], "auto", 0d, 1.3d, SourceComment: "Strength of Sharpening, \nvalue range between 0.0 and 1.0 (while using upper limit is RCAS 1.3) - Default (auto) is 0.3"),
        new("OutputScaling.Enabled", new IniKey("OutputScaling", "Enabled"), "Enabled", string.Empty, "OutputScaling", 222, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enable Output Scaling option for Dx12 and Dx11 with Dx12 backends\ntrue or false - Default (auto) is false"),
        new("OutputScaling.Multiplier", new IniKey("OutputScaling", "Multiplier"), "Multiplier", string.Empty, "OutputScaling", 223, SettingValueKind.Double, true, [], "auto", 0.5d, 3d, SourceComment: "Output Scaling ratio \n0.5 - 3.0 - Default (auto) is 1.5"),
        new("OutputScaling.Downscaler", new IniKey("OutputScaling", "Downscaler"), "Downscaler", string.Empty, "OutputScaling", 224, SettingValueKind.Enum, true, [new("0", "FSR1"), new("1", "Bicubic"), new("2", "CatmullRom"), new("3", "Lanczos2"), new("4", "Lanczos3"), new("5", "Kaiser2"), new("6", "Kaiser3"), new("7", "Magic")], "auto", 0d, 7d, SourceComment: "Downscaler to use for Output Scaling\n0 = FSR1 | 1 = Bicubic | 2 = Catmull-Rom | 3 = Lanczos2 | 4 = Lanczos3 | 5 = Kaiser2 | 6 = Kaiser3 | 7 = MAGIC\n0 to 7 - Default (auto) is 0 (FSR1)"),
        new("CAS.Enabled", new IniKey("CAS", "Enabled"), "Enabled", string.Empty, "CAS", 225, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enables RCAS sharpening \ntrue or false - Default (auto) is false"),
        new("CAS.MotionSharpnessEnabled", new IniKey("CAS", "MotionSharpnessEnabled"), "MotionSharpnessEnabled", string.Empty, "CAS", 226, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enable Motion Sharpness\ntrue or false - Default (auto) is false"),
        new("CAS.MotionSharpness", new IniKey("CAS", "MotionSharpness"), "MotionSharpness", string.Empty, "CAS", 227, SettingValueKind.Double, true, [], "auto", -1.3d, 1.3d, SourceComment: "Sharpening will be added or removed according to motion length\nvalue range between -1.3 and 1.3 - Default (auto) is 0.4"),
        new("CAS.MotionThreshold", new IniKey("CAS", "MotionThreshold"), "MotionThreshold", string.Empty, "CAS", 228, SettingValueKind.Double, true, [], "auto", 0d, 100d, SourceComment: "How much a pixel should move before Motion Sharpness is applied\n0.0 - 100.0 - Default (auto) is 0.0"),
        new("CAS.MotionScaleLimit", new IniKey("CAS", "MotionScaleLimit"), "MotionScaleLimit", string.Empty, "CAS", 229, SettingValueKind.Double, true, [], "auto", 0.01d, 100d, SourceComment: "How much a pixel should move to reach maximum MotionSharpness value \nValues between MotionThreshold and this value will use be used to scale sharpness value\n0.0 - 100.0 - Default (auto) is 10.0"),
        new("CAS.ContrastEnabled", new IniKey("CAS", "ContrastEnabled"), "ContrastEnabled", string.Empty, "CAS", 230, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enable Contrast based sharpening \nIncreases sharpness at high contrast areas.\ntrue or false - Default (auto) is false"),
        new("CAS.Contrast", new IniKey("CAS", "Contrast"), "Contrast", string.Empty, "CAS", 231, SettingValueKind.Double, true, [], "auto", -2d, 2d, SourceComment: "Contrast based sharpening value\nHigher values increases sharpness at high contrast areas.\nHigh values might cause graphical GLITCHES when used with high sharpness values !!!\n0.0 - 2.0  - Default (auto) is 0.0"),
        new("CAS.SharpenerDebug", new IniKey("CAS", "SharpenerDebug"), "SharpenerDebug", string.Empty, "CAS", 232, SettingValueKind.Boolean, true, [], "auto", null, null, SourceComment: "Enable Debug Highlighting for Motion/DA Sharpening\nReddish hue for added, greenish for reduced sharpness\nBlue tint for detected edges in Depth Aware sharpening\ntrue or false - Default (auto) is false"),
        new("CAS.DADepthScale", new IniKey("CAS", "DADepthScale"), "DADepthScale", string.Empty, "CAS", 233, SettingValueKind.Double, true, [], "auto", null, null, SourceComment: "Controls how strongly sharpening is reduced across depth edges.\nHigher values more aggressively block sharpening at object boundaries (reduces halos).\nLower values allow more sharpening across edges (sharper, but riskier).\n2.0 - 600.0  - Default (auto) is 4.0"),
        new("CAS.DADepthBias", new IniKey("CAS", "DADepthBias"), "DADepthBias", string.Empty, "CAS", 234, SettingValueKind.Double, true, [], "auto", null, null, SourceComment: "Ignores small depth differences before edge detection.\nHigher values reduce noise and flickering from minor depth changes.\nLower values preserve fine detail, but may react to depth noise.\n0.005 - 0.03  - Default (auto) is 0.01"),
